"Um fundo novo aplica-se ao ecrã bloqueado e ao ecrã principal. Em Personalizar podes mudar cada um: cor, gradiente, uma foto ou desfocar o ecrã principal.": "새 배경 화면은 잠금 화면과 홈 화면에 적용됩니다. 사용자화에서 각각 색상, 그라디언트, 사진을 바꾸거나 홈 화면을 흐리게 할 수 있습니다.",
"Também podes manter pressionado o ecrã bloqueado para ver e trocar todos os fundos.": "잠금 화면을 길게 눌러 모든 배경 화면을 보고 바꿀 수도 있습니다.",
