"Nunca: o cartão mostra só o nome da app, sem o texto. Quando desbloqueado: o texto só aparece com o PearPhone desbloqueado.": "안 함: 카드에 텍스트 없이 앱 이름만 표시됩니다. 잠금 해제됨: PearPhone이 잠금 해제된 경우에만 텍스트가 표시됩니다.",
"Nenhuma app mostra notificações. As chamadas continuam a tocar.": "어떤 앱도 알림을 표시하지 않습니다. 전화는 계속 울립니다.",
