"Só um modo de cada vez. Com qualquer modo ligado as notificações ficam silenciosas e sem avisos flutuantes, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "한 번에 하나의 모드만 사용할 수 있습니다. 모드를 켜면 \"방해 금지 모드\"처럼 알림이 무음이 되고 플로팅 알림이 표시되지 않습니다. 업무와 수면에는 아직 허용 앱 목록이 없습니다.",
"Só um foco de cada vez. Com qualquer foco ligado as notificações ficam silenciosas e sem banners, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "한 번에 하나의 집중 모드만 사용할 수 있습니다. 집중 모드를 켜면 \"방해 금지 모드\"처럼 알림이 무음이 되고 배너가 표시되지 않습니다. 업무와 수면에는 아직 허용 앱 목록이 없습니다.",
