"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada nas apps recentes ou quando sais.": "각 외부 앱이 내 이름으로 할 수 있도록 서버가 허용하는 항목입니다. \"한 번\"은 최근 사용한 앱에서 앱을 닫거나 로그아웃하면 끝납니다.",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada no alternador ou quando sais.": "각 외부 앱이 내 이름으로 할 수 있도록 서버가 허용하는 항목입니다. \"한 번\"은 앱 전환기에서 앱을 닫거나 로그아웃하면 끝납니다.",
"%s · uma vez": "%s · 한 번",
