"Compra e vende veículos, casas e mais. Carros, casas e tudo o resto, num toque.": "차량, 집 등을 사고팔아요. 자동차, 집, 그 밖의 모든 것을 한 번의 탭으로.",
"Conhece pessoas em Los Santos. Desliza, combina, conversa.": "Los Santos에서 사람들을 만나 보세요. 넘기고, 매칭하고, 대화하세요.",
"Pede polícia, EMS, mecânico, táxi e mais. Pede ajuda com a tua localização.": "경찰, 응급 구조, 정비사, 택시 등을 불러요. 내 위치와 함께 도움을 요청하세요.",
"O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes. O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes.": "클래식 게임. 먹고, 자라고, 자기 몸을 물지 마세요. 과일 다섯 개마다 빨라지고, 벽이 있거나 없이 즐길 수 있어요. 클래식 게임. 먹고, 자라고, 자기 몸을 물지 마세요. 과일 다섯 개마다 빨라지고, 벽이 있거나 없이 즐길 수 있어요.",
"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "공을 떨어뜨리지 않고 모든 벽돌을 깨세요. 단단한 벽돌, 떨어지는 보너스, 끝없는 레벨이 있어요. 공을 떨어뜨리지 않고 모든 벽돌을 깨세요. 단단한 벽돌, 떨어지는 보너스, 끝없는 레벨이 있어요.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "내 차량, 위치, 차고. 위치를 찾고, 즐겨찾기에 추가하고, 별명을 지어 보세요.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "별명으로 입장하는 익명 대화방. 메시지는 서버에 저장돼요. 별명으로 입장. 메시지는 서버에 남아요.",
"Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números. Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números.": "지뢰를 건드리지 않고 필드를 밝혀 보세요. 세 가지 난이도, 깃발 모드, 숫자 주변 자동 열기. 지뢰를 건드리지 않고 필드를 밝혀 보세요. 세 가지 난이도, 깃발 모드, 숫자 주변 자동 열기.",
"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "휴대폰의 모든 게임을 한곳에, 내 기록과 마지막으로 플레이한 게임까지. 휴대폰의 모든 게임을 한곳에, 내 기록과 마지막으로 플레이한 게임까지.",
"Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais. Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais.": "AI 어시스턴트: 서버와 휴대폰 관련 질문, 계산, 날씨 등. AI 어시스턴트: 서버와 휴대폰 관련 질문, 계산, 날씨 등.",
"Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua. Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua.": "나와 위치를 공유하는 가족과 친구가 어디 있는지 확인하고, 내 위치도 공유하세요. 나와 위치를 공유하는 가족과 친구가 어디 있는지 확인하고, 내 위치도 공유하세요.",
